public sealed class BoardConfiguration : IEntityTypeConfiguration<Board>
{
    public void Configure(EntityTypeBuilder<Board> builder)
    {
        builder.ToTable("boards"); builder.HasKey(x => x.Id); builder.Property(x => x.Id).HasColumnName("id"); builder.Property(x => x.EventId).HasColumnName("event_id"); builder.HasIndex(x => x.EventId).IsUnique(); builder.Property(x => x.Name).HasColumnName("name").HasMaxLength(200); builder.Property(x => x.Rows).HasColumnName("rows"); builder.Property(x => x.Columns).HasColumnName("columns"); builder.Property(x => x.State).HasColumnName("state").HasConversion<string>().HasMaxLength(30); builder.Property(x => x.PublishedAt).HasColumnName("published_at"); builder.Property(x => x.TotalEhbEstimate).HasColumnName("total_ehb_estimate").HasPrecision(14, 4); builder.Property(x => x.CalculationVersion).HasColumnName("calculation_version"); builder.Property(x => x.Version).HasColumnName("version").IsConcurrencyToken(); builder.Property(x => x.ActiveApprovalSnapshotId).HasColumnName("active_approval_snapshot_id"); builder.Property(x => x.PublishedCorrectionInProgress).HasColumnName("published_correction_in_progress"); builder.Property(x => x.EditorAccountId).HasColumnName("editor_account_id"); builder.Property(x => x.EditorLeaseExpiresAt).HasColumnName("editor_lease_expires_at"); builder.Property(x => x.EditControlVersion).HasColumnName("edit_control_version").IsConcurrencyToken();
        builder.HasOne<BoardApprovalSnapshot>().WithMany().HasForeignKey(x => x.ActiveApprovalSnapshotId).OnDelete(DeleteBehavior.SetNull);
    }
}
