public sealed class BoardApprovalSnapshotConfiguration : IEntityTypeConfiguration<BoardApprovalSnapshot>
{
    public void Configure(EntityTypeBuilder<BoardApprovalSnapshot> builder)
    {
        builder.ToTable("board_approval_snapshots"); builder.HasKey(x => x.Id); builder.Property(x => x.Id).HasColumnName("id"); builder.Property(x => x.BoardId).HasColumnName("board_id"); builder.Property(x => x.Version).HasColumnName("version"); builder.HasIndex(x => new { x.BoardId, x.Version }).IsUnique(); builder.Property(x => x.ApprovedAt).HasColumnName("approved_at"); builder.Property(x => x.ApprovedByAccountId).HasColumnName("approved_by_account_id"); builder.Property(x => x.SupersedesApprovalSnapshotId).HasColumnName("supersedes_approval_snapshot_id"); builder.Property(x => x.Name).HasColumnName("name").HasMaxLength(200); builder.Property(x => x.Rows).HasColumnName("rows"); builder.Property(x => x.Columns).HasColumnName("columns"); builder.Property(x => x.TotalEhbEstimate).HasColumnName("total_ehb_estimate").HasPrecision(14, 4); builder.Property(x => x.CalculationVersion).HasColumnName("calculation_version"); builder.Property(x => x.BoardVersion).HasColumnName("board_version"); builder.Property(x => x.LifecycleState).HasColumnName("lifecycle_state").HasConversion<string>().HasMaxLength(30);
        builder.HasOne<Board>().WithMany().HasForeignKey(x => x.BoardId).OnDelete(DeleteBehavior.Cascade);
        builder.HasOne<BoardApprovalSnapshot>().WithMany().HasForeignKey(x => x.SupersedesApprovalSnapshotId).OnDelete(DeleteBehavior.Restrict);
    }
}
